export const getSearchCatalogueUrl = (eventId: string,
    params: SearchCatalogueParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/events/${eventId}/catalogue?${stringifiedParams}` : `/api/events/${eventId}/catalogue`
}

