export const getSearchGuestCatalogueUrl = (token: string,
    params: SearchGuestCatalogueParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/guest/${token}/catalogue?${stringifiedParams}` : `/api/guest/${token}/catalogue`
}

